body.script:
/* Boot guard: prints JavaScript errors on screen (hosted copies included). */
(function(){
  function paint(text){
    var bar = document.getElementById('bootError');
    if (!bar){
      bar = document.createElement('div');
      bar.id = 'bootError';
      bar.style.cssText = 'position:fixed;left:0;right:0;bottom:0;z-index:2147483647;padding:10px 14px;background:#7f1d1d;color:#fff;font:12px/1.5 ui-monospace,Consolas,monospace;white-space:pre-wrap;max-height:45vh;overflow:auto;border-top:2px solid #ef4444';
      (document.body || document.documentElement).appendChild(bar);
    }
    bar.textContent += text + '\n';
  }
  window.addEventListener('error', function (event){
    var target = event && event.target;
    if (target && target !== window && target.tagName){
      paint('Could not load ' + target.tagName.toLowerCase() + ': ' + (target.src || target.href || ''));
      return;
    }
    var msg = (event && event.message) || 'Script error';
    var at = event && event.lineno ? ' (line ' + event.lineno + (event.colno ? ':' + event.colno : '') + ')' : '';
    paint('JS error: ' + msg + at);
  }, true);
})();

input.script:
(() => {
  'use strict';

  const REPO = { owner: 'nguyenkhoinguyen08012012-stack', repo: 'webs', branch: 'main' };
  const API_TREE = `https://api.github.com/repos/${REPO.owner}/${REPO.repo}/git/trees/${REPO.branch}?recursive=1`;
  const RAW_BASE = `https://raw.githubusercontent.com/${REPO.owner}/${REPO.repo}/${REPO.branch}/`;

  /* Extra library: the "all" repo stores HTML apps with .xml names */
  const EXTRA_REPO = { owner: 'nguyenkhoinguyen08012012-stack', repo: 'all', branch: 'main' };
  const EXTRA_RAW_BASE = `https://raw.githubusercontent.com/${EXTRA_REPO.owner}/${EXTRA_REPO.repo}/${EXTRA_REPO.branch}/`;
  const BLOB_MANGA_URL = 'https://raw.githubusercontent.com/nguyenkhoinguyen08012012-stack/all/refs/heads/main/manga-readerv2.xml';
  const EXTRA_APPS = [
    ['all.xml', 6485],
    ['allmoandgam.xml', 5233],
    ['allmovies.xml', 2552],
    ['deltamathall.xml', 6710],
    ['gnmath1.xml', 37351],
    ['gnmath2.xml', 37403],
    ['gnmath3.xml', 912426],
    ['gnmath4.xml', 74163],
    ['slashallga.xml', 6111]
  ].map(([file, size]) => ({
    name: file.replace(/\.xml$/i, '.html'),
    size,
    url: EXTRA_RAW_BASE + file
  }));

  /* Apps baked into this file: they need no repo, no network, and no second download */
  const EMBEDDED_APP_SOURCES = {
    'Manga Reader.html': { nodeId: 'embedded-manga-reader', size: 286190 }
  };

  const EMBEDDED_APPS = Object.keys(EMBEDDED_APP_SOURCES).map((name) => ({
    name,
    size: EMBEDDED_APP_SOURCES[name].size,
    embedded: true
  }));

  /* Repo files that must not show up as cards: the stale reader stub, and the
     hosted copies that the Apps Script loader serves (/exec and /exec?app=manga). */
  const REPLACED_APPS = new Set(['manga.html', 'manga-reader.html', 'index.html']);

  const PLAY_SVG = '';
  const STAR_SVG = '';
  const EYE_OFF_SVG = '';
  const EYE_SVG = '';

  /* Bundled fallback manifest: keeps the launcher usable if the GitHub API is unreachable */
  const BUNDLED_RAW = [
    ["Afterspace - Entertainment.html", 868107],
    ["astra18.html", 39213356],
    ["bankerd.html", 2440931],
    ["blober eatmanerer.html", 2440764],
    ["blockspin.html", 2440987],
    ["bodydrop3d.html", 2440989],
    ["car vs police.html", 2440977],
    ["ch op tr ee.html", 3894],
    ["chess persiut.html", 2440994],
    ["clash roy.html", 2440972],
    ["classroommaxxing.html", 21977839],
    ["climbhard.html", 2440971],
    ["cloakedalgam.html", 26985],
    ["cut the rope.html", 2440990],
    ["dig prison.html", 2440990],
    ["dirt bike.html", 2440986],
    ["DragonX_V2_International.html", 25894581],
    ["Dragonxclient.html", 19818631],
    ["dragonxv3.html", 22084832],
    ["eventide.html", 2440983],
    ["extremebattle.html", 8646],
    ["flipper.html", 2440971],
    ["geometry dash editor.html", 2440947],
    ["github sreach.html", 2440994],
    ["gun kight.html", 2440986],
    ["GX-Launcher-Mini.html", 49734],
    ["Hak1.12.2.html", 22458280],
    ["jusinv3hakclient.html", 27938913],
    ["logicgate.html", 426318],
    ["m c mo tor.html", 3890],
    ["make sure it close.html", 2441004],
    ["mc1.6.4modpack.html", 61200294],
    ["mc112.html", 2440974],
    ["mc18.html", 2440971],
    ["mc26.2.html", 75596271],
    ["Mr bullet.html", 2440982],
    ["no brake car.html", 2440975],
    ["obby univese.html", 2440990],
    ["on ly up 2 d.html", 3878],
    ["PixelClient.html", 42915595],
    ["PUGPIXELLL.html", 2444028],
    ["rando area.html", 2440988],
    ["randoruner.html", 2440991],
    ["resent.html", 18831111],
    ["roblox Iq test.html", 2440993],
    ["sand box robloxx.html", 2440947],
    ["sand box.html", 2440974],
    ["sandbox studio.html", 2440993],
    ["sla p aur a.html", 3876],
    ["slowroadd.html", 2440977],
    ["sniper city.html", 2440940],
    ["sou nd effe ct.html", 3878],
    ["ta nk fl ow.html", 3879],
    ["talloio.html", 2440935],
    ["tap car.html", 2440980],
    ["taxi drive.html", 2440986],
    ["tenacity.html", 2440985],
    ["territorialioo.html", 2440998],
    ["the last one.html", 2440992],
    ["the martiz.html", 2440989],
    ["topgun.html", 2440976],
    ["towel bloxd.html", 2440989],
    ["trapventure.html", 2440994],
    ["UwU-client-b2-offline.html", 38856740],
    ["zo ne surv ival.html", 3876],
    ["zodiac.html", 7634]
  ];

  const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  const LETTER_ORDER = [...LETTERS, '#'];

  const LS = {
    settings: 'webs.launcher.v2.settings',
    favorites: 'webs.launcher.v2.favorites',
    recent: 'webs.launcher.v2.recent',
    hidden: 'webs.launcher.v2.hidden',
    broken: 'webs.launcher.v2.broken',
    manifest: 'webs.launcher.v2.manifest',
    inspect: 'webs.launcher.v2.inspectUrl',
    inspectProxy: 'webs.launcher.v2.inspectProxy',
    inspectProxyUrl: 'webs.launcher.v2.inspectProxyUrl',
    inspectScripts: 'webs.launcher.v2.inspectScripts',
    inspectPretty: 'webs.launcher.v2.inspectPretty'
  };

  const DEFAULTS = {
    compact: false,
    glow: true,
    reduceMotion: false,
    hideBar: false,
    autoHideBar: false,
    groupByName: true,
    showSizes: true,
    hideBroken: true,
    sort: 'az',
    autoHidePlayerBar: true
  };

  const $ = (id) => document.getElementById(id);
  const ui = {
    topbar: $('topbar'), revealBar: $('revealBar'), hideBar: $('hideBar'),
    q: $('q'), source: $('source'), sourceLabel: $('sourceLabel'),
    refresh: $('refresh'), blobMangaBtn: $('blobMangaBtn'), openFile: $('openFile'), random: $('random'), settingsBtn: $('settingsBtn'),
    inspectBtn: $('inspectBtn'), filtersBar: $('filtersBar'), urlHit: $('urlHit'),
    count: $('count'), totalSize: $('totalSize'), hiddenStat: $('hiddenStat'), sort: $('sort'),
    chips: $('chips'), list: $('list'), empty: $('empty'), emptyTitle: $('emptyTitle'),
    emptyText: $('emptyText'), emptyClear: $('emptyClear'), fileInput: $('fileInput'),
    toast: $('toast'), drop: $('drop'),
    inspector: $('inspector'), insForm: $('insForm'), insUrl: $('insUrl'), insGo: $('insGo'),
    insOpen: $('insOpen'), insReload: $('insReload'), insClose: $('insClose'),
    insProxy: $('insProxy'), insCustomWrap: $('insCustomWrap'), insCustomProxy: $('insCustomProxy'),
    insScripts: $('insScripts'), insEdit: $('insEdit'),
    insPreview: $('insPreview'), insFrame: $('insFrame'), insHover: $('insHover'), insSel: $('insSel'),
    insState: $('insState'), insStateTitle: $('insStateTitle'), insStateText: $('insStateText'),
    insTree: $('insTree'), insDetail: $('insDetail'), insSource: $('insSource'), insMeta: $('insMeta'),
    insElementsPane: $('insElementsPane'), insSourcePane: $('insSourcePane'),
    insFormat: $('insFormat'), insSourceInfo: $('insSourceInfo'), insCopySource: $('insCopySource'),
    insEditSource: $('insEditSource'), insApplySource: $('insApplySource'), insLaunchSource: $('insLaunchSource'),
    insSourceWrap: $('insSourceWrap'), insSourceScroll: $('insSourceScroll'), insGutter: $('insGutter'),
    insSourceEdit: $('insSourceEdit'), insSourceNote: $('insSourceNote'),
    insConsolePane: $('insConsolePane'), insConsoleCount: $('insConsoleCount'),
    insConsoleHint: $('insConsoleHint'), insConsoleClear: $('insConsoleClear'),
    insLogs: $('insLogs'), insPrompt: $('insPrompt'), insPromptInput: $('insPromptInput'),
    insNetworkPane: $('insNetworkPane'), insNetCount: $('insNetCount'), insNetHint: $('insNetHint'),
    insNetClear: $('insNetClear'), insNetList: $('insNetList'), insNetDetail: $('insNetDetail'),
    player: $('player'), pbar: $('pbar'), pClose: $('pClose'), pName: $('pName'), pMeta: $('pMeta'),
    pStatus: $('pStatus'), pBlank: $('pBlank'), pExternal: $('pExternal'),
    pReload: $('pReload'), pBar: $('pBar'), pFull: $('pFull'), pBarReveal: $('pBarReveal'),
    frame: $('frame'), loader: $('loader'), loadTitle: $('loadTitle'), loadSub: $('loadSub'),
    progress: $('progress'), bar: $('bar'), pct: $('pct'), bytes: $('bytes'),
    error: $('error'), errMsg: $('errMsg'), errBack: $('errBack'), errRetry: $('errRetry'),
    scrim: $('scrim'), settings: $('settings'), setClose: $('setClose'), setStats: $('setStats'),
    scanNote: $('scanNote')
  };

  /* ---------------- storage ---------------- */
  const store = {
    read(key, fallback){
      try {
        const raw = localStorage.getItem(key);
        if (raw === null) return fallback;
        const value = JSON.parse(raw);
        return value === null || value === undefined ? fallback : value;
      } catch (err){ return fallback; }
    },
    write(key, value){
      try { localStorage.setItem(key, JSON.stringify(value)); } catch (err){ /* private mode */ }
    },
    remove(key){
      try { localStorage.removeItem(key); } catch (err){ /* ignore */ }
    }
  };

  function stringSet(value){
    if (!Array.isArray(value)) return new Set();
    return new Set(value.filter((x) => typeof x === 'string'));
  }

  let settings = Object.assign({}, DEFAULTS, store.read(LS.settings, {}));
  delete settings.groupByCategory;
  delete settings.showTags;
  let favorites = stringSet(store.read(LS.favorites, []));
  let manualHidden = stringSet(store.read(LS.hidden, []));
  let broken = stringSet(store.read(LS.broken, []));
  let recent = store.read(LS.recent, []);
  if (!Array.isArray(recent)) recent = [];
  recent = recent.filter((x) => typeof x === 'string').slice(0, 18);

  let files = [];
  let query = '';
  let currentGroup = 'all';
  let manifestState = 'bundled';
  let manifestBusy = false;
  let scanning = false;

  /* ---------------- helpers ---------------- */
  function formatSize(n){
    if (!n || n < 0 || !isFinite(n)) return '—';
    if (n < 1024) return n + ' B';
    if (n < 1048576) return (n / 1024).toFixed(n < 10240 ? 1 : 0) + ' KB';
    if (n < 1073741824) return (n / 1048576).toFixed(n < 10485760 ? 1 : 0) + ' MB';
    return (n / 1073741824).toFixed(1) + ' GB';
  }

  function formatSpeed(bytesPerSecond){
    if (!bytesPerSecond || !isFinite(bytesPerSecond) || bytesPerSecond <= 0) return '';
    if (bytesPerSecond < 1048576) return Math.max(1, Math.round(bytesPerSecond / 1024)) + ' KB/s';
    return (bytesPerSecond / 1048576).toFixed(1) + ' MB/s';
  }

  function cleanTitle(name){
    return name.replace(/\.html?$/i, '').trim();
  }

  function monogram(name){
    const words = cleanTitle(name).replace(/[^a-z0-9]+/gi, ' ').trim().split(/\s+/).filter(Boolean);
    return (((words[0] || '?')[0] || '?') + ((words[1] || '')[0] || '')).toUpperCase();
  }

  function hueOf(name){
    let h = 0;
    for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
    return h % 360;
  }

  function letterOf(name){
    const first = cleanTitle(name).replace(/^[\s._-]+/, '').charAt(0).toUpperCase();
    return /^[A-Z]$/.test(first) ? first : '#';
  }

  function letterColor(letter){
    if (letter === '#') return '#94a3b8';
    return `hsl(${(letter.charCodeAt(0) * 53 + 195) % 360} 72% 63%)`;
  }

  function groupOrder(){
    const present = new Set(files.map((f) => f.group));
    return LETTER_ORDER.filter((key) => present.has(key));
  }

  function groupOf(name){
    return letterOf(name);
  }

  function normalize(list){
    const seen = new Set();
    const out = [];
    for (const item of list || []){
      const name = item && (item.name || item.n);
      const size = Number(item && (item.size ?? item.s)) || 0;
      const url = item && typeof item.url === 'string' ? item.url : '';
      if (typeof name !== 'string' || (!/\.html?$/i.test(name) && !url)) continue;
      if (name.includes('/') || name.includes('\\') || seen.has(name)) continue;
      if (REPLACED_APPS.has(name)) continue;
      seen.add(name);
      const embedded = !!(item && item.embedded) ||
        Object.prototype.hasOwnProperty.call(EMBEDDED_APP_SOURCES, name);
      const realSize = embedded ? (EMBEDDED_APP_SOURCES[name].size || size) : size;
      out.push({ name, size: realSize, group: groupOf(name), url, embedded });
    }
    return out;
  }

  function mergeExtraApps(list){
    const merged = Array.isArray(list) ? list.slice() : [];
    const names = new Set(merged.map((item) => item && (item.name || item.n)).filter(Boolean));
    [...EXTRA_APPS, ...EMBEDDED_APPS].forEach((app) => {
      if (!names.has(app.name)){
        merged.push(app);
        names.add(app.name);
      }
    });
    return merged;
  }

  const BUNDLED = normalize(BUNDLED_RAW.map(([name, size]) => ({ name, size })));

  function isWorking(file){ return !broken.has(file.name); }

  function isQueryMatch(file){
    if (!query) return true;
    const title = cleanTitle(file.name).toLowerCase();
    const q = query.trim().toLowerCase();
    if (!q) return true;
    if (title.includes(q)) return true;
    const squash = (s) => s.replace(/[\s_-]+/g, '');
    return squash(title).includes(squash(q));
  }

  function normalizeInspectUrl(value){
    let raw = String(value || '').trim();
    if (!raw || /\s/.test(raw)) return '';
    if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)) raw = 'https://' + raw;
    let url;
    try { url = new URL(raw); } catch (err){ return ''; }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return '';
    return url.href;
  }

  function urlFromQuery(value){
    const raw = String(value || '').trim();
    if (!raw || /\s/.test(raw)) return '';
    const host = /^(https?:\/\/)?(localhost|(\d{1,3}\.){3}\d{1,3}|([a-z0-9-]+\.)+[a-z]{2,})(:\d+)?([/?#].*)?$/i;
    if (!host.test(raw)) return '';
    return normalizeInspectUrl(raw);
  }

  function inGroup(file, group){
    const hidden = manualHidden.has(file.name) || (settings.hideBroken && broken.has(file.name));
    if (group === 'hidden') return manualHidden.has(file.name) || broken.has(file.name);
    if (hidden) return false;
    if (group === 'recent') return recent.includes(file.name);
    if (group === 'favorites') return favorites.has(file.name);
    if (group === 'all') return true;
    return file.group === group;
  }

  function sortFiles(list){
    const mode = settings.sort;
    const byName = (a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' });
    if (mode === 'za') return list.sort((a, b) => byName(b, a));
    if (mode === 'big') return list.sort((a, b) => (b.size || 0) - (a.size || 0) || byName(a, b));
    if (mode === 'small') return list.sort((a, b) => (a.size || 0) - (b.size || 0) || byName(a, b));
    if (mode === 'recent'){
      const rank = (f) => { const i = recent.indexOf(f.name); return i < 0 ? Number.MAX_SAFE_INTEGER : i; };
      return list.sort((a, b) => rank(a) - rank(b) || byName(a, b));
    }
    return list.sort(byName);
  }

  function persistSettings(){ store.write(LS.settings, settings); }
  function persistFavorites(){ store.write(LS.favorites, [...favorites]); }
  function persistHidden(){
    store.write(LS.hidden, [...manualHidden]);
    store.write(LS.broken, [...broken]);
  }
  function persistRecent(){ store.write(LS.recent, recent); }

  function toast(message, tone){
    ui.toast.textContent = message;
    ui.toast.className = 'toast show' + (tone ? ' ' + tone : '');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { ui.toast.className = 'toast'; }, 2900);
  }
  let toastTimer = 0;

  let autoBarHidden = false;

  /* ---------------- source badge ---------------- */
  function setSource(state){
    manifestState = state;
    ui.source.className = 'source' + (state === 'live' ? ' live' : state === 'cached' ? ' cached' : '');
    ui.sourceLabel.textContent = state;
    ui.source.title = state === 'live'
      ? 'App list loaded live from the library'
      : state === 'cached'
        ? 'App list restored from this browser’s cache'
        : 'Using the app list bundled into this page';
  }

  /* ---------------- settings ---------------- */
  function isBarHidden(){
    return !!settings.hideBar || (!!settings.autoHideBar && autoBarHidden);
  }

  function applyBarState(){
    const hidden = isBarHidden();
    document.body.classList.toggle('bar-hidden', hidden);
    ui.revealBar.tabIndex = hidden ? 0 : -1;
    scheduleTopbarSync();
  }

  function applySettings(){
    document.body.classList.toggle('compact', !!settings.compact);
    document.body.classList.toggle('no-glow', !settings.glow);
    document.body.classList.toggle('reduce-motion', !!settings.reduceMotion);
    ui.sort.value = settings.sort;
    document.querySelectorAll('[data-setting="sort"]').forEach((sel) => { sel.value = settings.sort; });
    applyBarState();
  }

  function syncSettingsUI(){
    document.querySelectorAll('[data-setting]').forEach((control) => {
      const key = control.getAttribute('data-setting');
      if (!(key in settings)) return;
      if (control.type === 'checkbox') control.checked = !!settings[key];
      else control.value = settings[key];
    });
    updateSettingsStats();
  }

  function hiddenCount(){
    return files.filter((f) => manualHidden.has(f.name) || broken.has(f.name)).length;
  }

  function updateSettingsStats(){
    const hidden = hiddenCount();
    if (ui.setStats){
      ui.setStats.textContent = `${files.length} apps · ${hidden} hidden · ${broken.size} marked broken`;
    }
    document.querySelectorAll('[data-count="hidden"]').forEach((node) => { node.textContent = String(hidden); });
  }

  /* ---------------- summary ---------------- */
  function updateSummary(){
    ui.count.textContent = String(files.length);
    const total = files.reduce((sum, f) => sum + (f.size || 0), 0);
    ui.totalSize.textContent = formatSize(total) + ' total';
    ui.q.placeholder = `Search ${files.length} apps or paste a URL…`;
    const hidden = hiddenCount();
    ui.hiddenStat.hidden = hidden === 0;
    ui.hiddenStat.textContent = `${hidden} hidden`;
    ui.hiddenStat.title = 'Show hidden and broken apps';
    updateSettingsStats();
  }

  /* ---------------- chips ---------------- */
  function makeChip(group, label, count, opts){
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'chip' + (opts && opts.color ? ' group-chip' : '') + (opts && opts.alert ? ' alert' : '');
    chip.dataset.group = group;
    chip.setAttribute('role', 'tab');
    chip.setAttribute('aria-selected', String(currentGroup === group));
    if (opts && opts.color) chip.style.setProperty('--c', opts.color);
    chip.append(document.createTextNode(label));
    const b = document.createElement('b');
    b.textContent = String(count);
    chip.append(b);
    chip.addEventListener('click', () => {
      currentGroup = group;
      render();
      ui.list.scrollIntoView({ block: 'start', behavior: settings.reduceMotion ? 'auto' : 'smooth' });
    });
    return chip;
  }

  function buildChips(){
    const frag = document.createDocumentFragment();
    frag.appendChild(makeChip('all', 'All', files.filter((f) => inGroup(f, 'all')).length));

    if (recent.length){
      const count = files.filter((f) => inGroup(f, 'recent')).length;
      if (count) frag.appendChild(makeChip('recent', 'Recent', count));
    }
    if (favorites.size){
      const count = files.filter((f) => inGroup(f, 'favorites')).length;
      if (count) frag.appendChild(makeChip('favorites', 'Favorites', count));
    }

    for (const key of groupOrder()){
      const count = files.filter((f) => inGroup(f, key)).length;
      if (!count) continue;
      frag.appendChild(makeChip(key, key, count, { color: letterColor(key) }));
    }

    const hidden = hiddenCount();
    if (hidden){
      frag.appendChild(makeChip('hidden', 'Hidden', hidden, { alert: true }));
    }

    ui.chips.replaceChildren(frag);
  }

  /* ---------------- cards ---------------- */
  function titleContent(name){
    const title = cleanTitle(name);
    const q = query.trim();
    if (!q) return document.createTextNode(title);
    const at = title.toLowerCase().indexOf(q.toLowerCase());
    if (at < 0) return document.createTextNode(title);
    const frag = document.createDocumentFragment();
    if (at > 0) frag.appendChild(document.createTextNode(title.slice(0, at)));
    const mark = document.createElement('mark');
    mark.textContent = title.slice(at, at + q.length);
    frag.append(mark, document.createTextNode(title.slice(at + q.length)));
    return frag;
  }

  function makeCard(file, index){
    const hue = hueOf(file.name);
    const card = document.createElement('div');
    card.className = 'card' + (manualHidden.has(file.name) || broken.has(file.name) ? ' is-hidden' : '');
    card.tabIndex = 0;
    card.setAttribute('role', 'button');
    card.setAttribute('aria-label', 'Run ' + cleanTitle(file.name));
    card.dataset.name = file.name;
    card.style.setProperty('--h', String(hue));
    card.style.setProperty('--h2', String((hue + 44) % 360));
    card.style.setProperty('--d', Math.min(index, 14) * 16 + 'ms');

    const thumb = document.createElement('div');
    thumb.className = 'thumb';

    const mono = document.createElement('span');
    mono.className = 'mono';
    mono.textContent = monogram(file.name);
    thumb.appendChild(mono);

    if (settings.showSizes){
      const size = document.createElement('span');
      size.className = 'size' + (file.size > 20 * 1048576 ? ' large' : '');
      size.textContent = formatSize(file.size);
      thumb.appendChild(size);
    }

    const play = document.createElement('span');
    play.className = 'play';
    play.innerHTML = '' + PLAY_SVG + '';
    thumb.appendChild(play);

    const acts = document.createElement('div');
    acts.className = 'card-acts';

    const fav = document.createElement('button');
    fav.type = 'button';
    fav.className = 'mini fav' + (favorites.has(file.name) ? ' on' : '');
    fav.title = favorites.has(file.name) ? 'Remove from favorites' : 'Add to favorites';
    fav.setAttribute('aria-label', fav.title);
    fav.innerHTML = STAR_SVG;
    fav.addEventListener('click', (event) => {
      event.stopPropagation();
      if (favorites.has(file.name)) favorites.delete(file.name);
      else favorites.add(file.name);
      persistFavorites();
      render();
    });

    const hide = document.createElement('button');
    hide.type = 'button';
    const restoring = currentGroup === 'hidden' || manualHidden.has(file.name);
    hide.className = 'mini hide' + (restoring ? ' on' : '');
    hide.title = restoring ? 'Restore to library' : 'Hide from library';
    hide.setAttribute('aria-label', hide.title);
    hide.innerHTML = restoring ? EYE_SVG : EYE_OFF_SVG;
    hide.addEventListener('click', (event) => {
      event.stopPropagation();
      toggleHidden(file);
    });

    acts.append(fav, hide);
    thumb.appendChild(acts);

    const meta = document.createElement('div');
    meta.className = 'meta';
    const title = document.createElement('span');
    title.className = 'title';
    title.appendChild(titleContent(file.name));
    const sub = document.createElement('span');
    sub.className = 'sub';

    const statuses = [];
    if (manualHidden.has(file.name)) statuses.push({ text: 'Hidden', bad: false });
    if (!isWorking(file)) statuses.push({ text: 'Not working', bad: true });

    if (statuses.length){
      statuses.forEach((s, i) => {
        if (i) sub.append(makeSep());
        const tag = document.createElement('i');
        tag.className = 'status' + (s.bad ? ' bad' : '');
        tag.textContent = s.text;
        sub.appendChild(tag);
      });
    } else if (settings.showSizes){
      const sz = document.createElement('span');
      sz.textContent = formatSize(file.size);
      sub.appendChild(sz);
    }

    meta.append(title, sub);
    card.append(thumb, meta);

    card.addEventListener('click', (event) => {
      if (event.target.closest('.card-acts')) return;
      run(file);
    });
    card.addEventListener('keydown', (event) => {
      if (event.target !== card) return;
      if (event.key === 'Enter' || event.key === ' '){
        event.preventDefault();
        run(file);
      }
    });

    return card;
  }

  function makeSep(){
    const sep = document.createElement('span');
    sep.className = 'sep';
    sep.textContent = '·';
    return sep;
  }

  function toggleHidden(file){
    const restore = currentGroup === 'hidden' || manualHidden.has(file.name);
    if (restore){
      manualHidden.delete(file.name);
      broken.delete(file.name);
      toast(`Restored ${cleanTitle(file.name)}`, 'good');
    } else {
      manualHidden.add(file.name);
      toast(`Hidden ${cleanTitle(file.name)} — see the Hidden group to restore it`);
    }
    persistHidden();
    render();
  }

  /* ---------------- render ---------------- */
  function makeBlock(label, color, items, startIndex){
    const section = document.createElement('section');
    section.className = 'group-block';

    if (label){
      const head = document.createElement('div');
      head.className = 'group-head';
      const dot = document.createElement('span');
      dot.className = 'gdot';
      dot.style.setProperty('--c', color);
      const h = document.createElement('h2');
      h.textContent = label;
      const count = document.createElement('span');
      count.className = 'gcount';
      count.textContent = String(items.length);
      head.append(dot, h, count);
      section.appendChild(head);
    }

    const grid = document.createElement('div');
    grid.className = 'grid';
    items.forEach((file, i) => grid.appendChild(makeCard(file, (startIndex || 0) + i)));
    section.appendChild(grid);
    return section;
  }

  const GLOBE_SVG = '';

  function makeUrlHit(url){
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'url-card';

    const icon = document.createElement('span');
    icon.className = 'url-ico';
    icon.innerHTML = GLOBE_SVG;

    const body = document.createElement('span');
    body.className = 'url-body';
    const label = document.createElement('span');
    label.className = 'url-label';
    label.textContent = 'Run & inspect URL';
    const strong = document.createElement('strong');
    strong.textContent = url;
    const small = document.createElement('small');
    small.textContent = 'Fetches the page and opens it with a Chrome-style element inspector';
    body.append(label, strong, small);

    const go = document.createElement('span');
    go.className = 'url-go';
    go.append(document.createTextNode('Inspect'));
    const kbd = document.createElement('kbd');
    kbd.textContent = '↵';
    go.append(kbd);

    btn.append(icon, body, go);
    btn.addEventListener('click', () => openInspector(url));
    return btn;
  }

  function render(){
    let visible = files.filter((f) => inGroup(f, currentGroup) && isQueryMatch(f));
    if (currentGroup === 'recent'){
      const rank = (f) => { const i = recent.indexOf(f.name); return i < 0 ? Number.MAX_SAFE_INTEGER : i; };
      visible.sort((a, b) => rank(a) - rank(b) || a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }));
    } else {
      visible = sortFiles(visible);
    }

    buildChips();
    updateSummary();

    const urlHit = urlFromQuery(query);
    ui.urlHit.hidden = !urlHit;
    ui.urlHit.replaceChildren(urlHit ? makeUrlHit(urlHit) : document.createTextNode(''));

    const frag = document.createDocumentFragment();
    if (settings.groupByName && currentGroup === 'all' && settings.sort !== 'recent'){
      let offset = 0;
      for (const key of groupOrder()){
        const items = visible.filter((f) => f.group === key);
        if (!items.length) continue;
        frag.appendChild(makeBlock(key, letterColor(key), items, offset));
        offset += items.length;
      }
      if (!offset && visible.length){
        frag.appendChild(makeBlock(null, null, visible, 0));
      }
    } else {
      const color = currentGroup.length === 1 ? letterColor(currentGroup) : null;
      frag.appendChild(makeBlock(null, color, visible, 0));
    }

    ui.list.replaceChildren(frag);
    ui.empty.hidden = visible.length !== 0 || !!urlHit;
    ui.emptyClear.hidden = !query && currentGroup === 'all';

    if (!visible.length){
      if (query){
        ui.emptyTitle.textContent = 'No matching apps';
        ui.emptyText.textContent = `Nothing matches “${query.trim()}”. Try fewer words, or drop an HTML file to run it.`;
      } else if (currentGroup === 'hidden'){
        ui.emptyTitle.textContent = 'Nothing hidden';
        ui.emptyText.textContent = 'Apps you hide, and apps that fail to load, show up here.';
      } else if (currentGroup === 'favorites'){
        ui.emptyTitle.textContent = 'No favorites yet';
        ui.emptyText.textContent = 'Use the star on any card to keep it in this group.';
      } else if (currentGroup === 'recent'){
        ui.emptyTitle.textContent = 'Nothing played yet';
        ui.emptyText.textContent = 'Apps you open will appear here.';
      } else {
        ui.emptyTitle.textContent = 'No apps in this group';
        ui.emptyText.textContent = 'Pick another group or clear the filters.';
      }
    }
  }

  function applyFiles(list, state){
    files = normalize(mergeExtraApps(list));
    const valid = new Set(files.map((f) => f.name));
    for (const name of [...manualHidden]) if (!valid.has(name)) manualHidden.delete(name);
    for (const name of [...broken]) if (!valid.has(name)) broken.delete(name);
    for (const name of [...favorites]) if (!valid.has(name)) favorites.delete(name);
    recent = recent.filter((name) => valid.has(name));

    if (currentGroup !== 'all' && currentGroup !== 'hidden' && currentGroup !== 'recent' && currentGroup !== 'favorites' && !files.some((f) => f.group === currentGroup)){
      currentGroup = 'all';
    }
    if (state) setSource(state);
    render();
  }

  /* ---------------- manifest ---------------- */
  async function loadManifest(manual){
    if (manifestBusy) return;
    manifestBusy = true;
    ui.refresh.disabled = true;
    ui.refresh.classList.add('spinning');

    try {
      if (navigator.onLine === false) throw new Error('offline');

      const res = await fetch(API_TREE, {
        cache: 'no-store',
        headers: { Accept: 'application/vnd.github+json' }
      });
      if (!res.ok) throw new Error('App list request failed (' + res.status + ')');

      const data = await res.json();
      const list = (data.tree || [])
        .filter((x) => x.type === 'blob' && /\.html?$/i.test(x.path) && !x.path.includes('/'))
        .map((x) => ({ name: x.path, size: x.size }));

      if (!list.length) throw new Error('No HTML files found');

      applyFiles(list, 'live');
      store.write(LS.manifest, { time: Date.now(), files: list });
      if (manual) toast(`List refreshed — ${files.length} apps`, 'good');
    } catch (err){
      const cached = store.read(LS.manifest, null);
      if (cached && Array.isArray(cached.files) && cached.files.length){
        applyFiles(cached.files, 'cached');
        if (manual) toast('The app list is unreachable — showing the cached list', 'bad');
      } else if (manual){
        toast('The app list is unreachable — showing the included list', 'bad');
      }
    } finally {
      manifestBusy = false;
      ui.refresh.disabled = false;
      ui.refresh.classList.remove('spinning');
      syncSettingsUI();
    }
  }

  /* ---------------- player state ---------------- */
  let playToken = 0;
  let abortCtl = null;
  let currentFile = null;
  let currentLocal = null;
  let currentUrl = null;
  let currentSrc = null;
  let currentKind = null;
  let lastFocus = null;
  let recentDirty = false;
  let pbarTimer = 0;
  const keptUrls = new Set();
  const nativeCache = new Map();

  function abortError(){ return new DOMException('Cancelled', 'AbortError'); }

  function resetFrame(){
    ui.frame.onload = null;
    ui.frame.removeAttribute('srcdoc');
    ui.frame.src = 'about:blank';
  }

  function setStatus(text, tone){
    ui.pStatus.hidden = !text;
    ui.pStatus.textContent = text || '';
    ui.pStatus.className = 'p-status' + (tone ? ' ' + tone : '');
  }

  function setPbarHidden(hidden){
    ui.player.classList.toggle('bar-hidden', !!hidden);
    ui.pBar.title = hidden ? 'Show player bar (H)' : 'Hide player bar (H)';
  }

  function schedulePbarHide(){
    clearTimeout(pbarTimer);
    if (!settings.autoHidePlayerBar || !document.fullscreenElement || ui.player.hidden) return;
    pbarTimer = setTimeout(() => setPbarHidden(true), 2600);
  }

  function addRecent(name){
    const at = recent.indexOf(name);
    if (at >= 0) recent.splice(at, 1);
    recent.unshift(name);
    if (recent.length > 18) recent.length = 18;
    persistRecent();
    recentDirty = true;
  }

  function markBroken(name){
    if (!name || broken.has(name)) return;
    broken.add(name);
    persistHidden();
    updateSettingsStats();
    toast(`${cleanTitle(name)} didn't load — moved to Hidden`, 'bad');
  }

  function clearBroken(name){
    if (!broken.delete(name)) return;
    persistHidden();
    updateSettingsStats();
  }

  /* ---------------- launch ---------------- */
  function run(file, localFile){
    if (!file || !file.name) return;

    playToken++;
    const token = playToken;

    if (abortCtl) abortCtl.abort();
    abortCtl = new AbortController();
    clearTimeout(pbarTimer);

    const wasOpen = !ui.player.hidden;
    if (!wasOpen) lastFocus = document.activeElement;

    if (currentUrl && !keptUrls.has(currentUrl)) URL.revokeObjectURL(currentUrl);
    currentUrl = null;
    currentSrc = null;

    resetFrame();

    ui.player.hidden = false;
    document.body.classList.add('playing');

    currentFile = file;
    currentLocal = localFile || null;
    currentKind = null;

    ui.pName.textContent = cleanTitle(file.name) || file.name;
    ui.frame.title = cleanTitle(file.name) || 'HTML app';
    ui.pMeta.textContent = [file.size ? formatSize(file.size) : '', localFile ? 'Local file' : 'HTML app'].filter(Boolean).join(' · ');
    setStatus('opening');
    ui.pBlank.disabled = true;

    ui.error.hidden = true;
    ui.loader.hidden = false;
    ui.progress.classList.remove('indet');
    ui.progress.setAttribute('aria-valuenow', '0');
    ui.bar.style.width = '0%';
    ui.pct.textContent = '0%';
    ui.bytes.textContent = '';
    ui.loadTitle.textContent = localFile ? 'Opening file…' : 'Loading app…';
    ui.loadSub.textContent = localFile ? 'Reading from your computer' : 'Finding the app';

    if (!ui.player.classList.contains('bar-hidden')) setPbarHidden(false);

    load(file, localFile, token).catch((err) => {
      if (token !== playToken) return;
      if (err && err.name === 'AbortError') return;
      fail(err);
    });
  }

  /* Google Apps Script (and its user-content iframe) answers unknown paths with the
     web app itself, so the local-copy probe would reload the launcher inside the player. */
  const sandboxHosted = /(^|\.)(script\.google\.com|googleusercontent\.com)$/i.test(location.hostname);

  async function load(file, localFile, token){
    if (localFile){
      currentKind = 'local';
      const text = await localFile.text();
      if (token !== playToken) return;
      if (!text && localFile.size) throw new Error('That file could not be read.');
      mountBlob(new Blob([text], { type: 'text/html;charset=utf-8' }), token);
      return;
    }

    if (!file.url && !file.embedded && !sandboxHosted && location.protocol !== 'file:'){
      ui.loadSub.textContent = 'Checking for a local copy';
      const native = await nativeUrl(file.name);
      if (token !== playToken) return;
      if (native){
        currentKind = 'native';
        setStatus('repo file');
        startFrame(native, token);
        return;
      }
    }

    setStatus('downloading');
    ui.loadSub.textContent = file.size > 20 * 1048576
      ? `Downloading ${formatSize(file.size)} — this is a big one`
      : 'Fetching the app';

    const blob = await download(file, token);
    if (token !== playToken) return;
    mountBlob(blob, token);
  }

  async function nativeUrl(name){
    if (nativeCache.has(name)) return nativeCache.get(name);
    try {
      const url = new URL(encodeURIComponent(name), location.href).href;
      const res = await fetch(url, { method: 'HEAD', cache: 'no-store' });
      const type = (res.headers.get('content-type') || '').toLowerCase();
      const ok = res.ok && type.includes('text/html');
      nativeCache.set(name, ok ? url : null);
      return ok ? url : null;
    } catch (err){
      nativeCache.set(name, null);
      return null;
    }
  }

  async function download(file, token){
    if (file.embedded){
      const blob = await embeddedBlob(file);
      if (token !== playToken) throw abortError();
      setProgress(blob.size, blob.size, performance.now(), true);
      return blob;
    }

    const path = encodeURIComponent(file.name);
    const sources = file.url
      ? [file.url]
      : [
          RAW_BASE + path,
          `https://cdn.statically.io/gh/${REPO.owner}/${REPO.repo}/${REPO.branch}/${path}`,
          `https://cdn.jsdelivr.net/gh/${REPO.owner}/${REPO.repo}@${REPO.branch}/${path}`
        ];

    let lastErr = null;
    for (const url of sources){
      if (token !== playToken) throw abortError();
      try {
        return await fetchBlob(url, token);
      } catch (err){
        if (err && err.name === 'AbortError') throw err;
        lastErr = err;
      }
    }
    throw lastErr || new Error('Every download source failed. Check your connection and try again.');
  }

  async function fetchBlob(url, token){
    const res = await fetch(url, { cache: 'default', signal: abortCtl ? abortCtl.signal : undefined });
    if (!res.ok) throw new Error('Download failed with HTTP ' + res.status + '.');
    if (token !== playToken) throw abortError();

    const total = Number(res.headers.get('content-length')) || 0;
    ui.progress.classList.toggle('indet', !total);

    if (!res.body){
      const blob = await res.blob();
      if (token !== playToken) throw abortError();
      return new Blob([blob], { type: 'text/html;charset=utf-8' });
    }

    const reader = res.body.getReader();
    const chunks = [];
    const started = performance.now();
    let received = 0;
    let lastPaint = 0;

    for (;;){
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
      received += value.length;

      const now = performance.now();
      if (now - lastPaint > 100){
        lastPaint = now;
        setProgress(received, total, started);
      }

      if (token !== playToken){
        try { await reader.cancel(); } catch (err){ /* ignore */ }
        throw abortError();
      }
    }

    if (token !== playToken) throw abortError();
    setProgress(received, total || received, started, true);
    ui.progress.classList.remove('indet');
    ui.bar.style.width = '100%';
    ui.pct.textContent = '100%';
    ui.progress.setAttribute('aria-valuenow', '100');

    return new Blob(chunks, { type: 'text/html;charset=utf-8' });
  }

  function setProgress(received, total, started, finished){
    const elapsed = Math.max(0.12, (performance.now() - started) / 1000);
    const speed = formatSpeed(received / elapsed);
    const pct = finished ? 100 : total > 0 ? Math.max(0, Math.min(100, (received / total) * 100)) : 0;

    if (total > 0){
      ui.bar.style.width = pct + '%';
      ui.pct.textContent = Math.floor(pct) + '%';
      ui.progress.setAttribute('aria-valuenow', String(Math.floor(pct)));
      ui.bytes.textContent = formatSize(received) + ' / ' + formatSize(total) + (speed ? ' · ' + speed : '');
    } else {
      ui.progress.classList.add('indet');
      ui.pct.textContent = formatSize(received);
      ui.bytes.textContent = speed || 'downloading…';
    }
  }

  const embeddedBlobCache = new Map();

