ScanLimit\", \"latestMissLimit\", \"width\", \"imageLoadMode\", \"imageProxyMode\", \"link\""]},{"start":1661,"del":0,"lines":["      imageLoadMode: \"blob\","]},{"start":1682,"del":0,"lines":["    imageLoadMode: \"blob\","]},{"start":1755,"del":0,"lines":["    if (!IMAGE_LOAD_MODES.has(group.imageLoadMode)) group.imageLoadMode = \"blob\";"]},{"start":3925,"del":1,"lines":["    clearPagesNode();"]},{"start":5094,"del":0,"lines":["  function imageLoadMode() {","    return IMAGE_LOAD_MODES.has(els.imageLoadMode?.value) ? els.imageLoadMode.value : \"blob\";","  }","","  function releaseImageBlob(img) {","    const objectUrl = img?._blobObjectUrl;","    if (!objectUrl) return;","    img._blobObjectUrl = \"\";","    try {","      URL.revokeObjectURL(objectUrl);","    } catch {","      /* The browser may already have released it. */","    }","  }","","  /* Fetch the chosen candidate into a Blob URL by default. A failed or blocked","     fetch falls back to the ordinary image URL so the retry chain still works. */","  async function setImageSource(img, url) {","    if (!img || !url) return false;","","    const seq = (img._loadSeq = (img._loadSeq || 0) + 1);","    const wrap = img.closest(\".page-wrap\");","    if (wrap) wrap.dataset.loadStarted = String(Date.now());","    delete img.dataset.offline;","","    if (imageLoadMode() !== \"blob\") {","      delete img.dataset.blobPending;","      releaseImageBlob(img);","      delete img.dataset.blob;","      img.src = url;","      return false;","    }","","    img.dataset.blobPending = \"1\";","    const controller = new AbortController();","    const timer = setTimeout(() =\u003e controller.abort(), IMAGE_FETCH_TIMEOUT_MS);","","    try {","      const response = await fetch(url, {","        mode: \"cors\",","        credentials: \"omit\",","        cache: \"force-cache\",","        referrerPolicy: \"no-referrer\",","        signal: controller.signal","      });","      if (!response.ok) throw new Error(`Image fetch failed: ${response.status}`);","","      const blob = await response.blob();","      if (!blob || !blob.size) throw new Error(\"Image fetch returned an empty file\");","      if (seq !== img._loadSeq || !img.isConnected) return false;","","      const objectUrl = URL.createObjectURL(blob);","      releaseImageBlob(img);","      img._blobObjectUrl = objectUrl;","      delete img.dataset.blobPending;","      img.dataset.blob = \"1\";","      img.src = objectUrl;","      return true;","    } catch {","      if (seq !== img._loadSeq || !img.isConnected) return false;","      releaseImageBlob(img);","      delete img.dataset.blobPending;","      delete img.dataset.blob;","      img.src = url;","      return false;","    } finally {","      clearTimeout(timer);","    }","  }","","  /* Revoke temporary Blob URLs before a page list is replaced. */","  function clearPagesNode(...nodes) {","    for (const img of els.pages.querySelectorAll(\"img\")) {","      img._loadSeq = (img._loadSeq || 0) + 1;","      releaseImageBlob(img);","    }","    els.pages.replaceChildren(...nodes);","  }","","  /* Re-fetch every displayed page as a Blob URL. Blob mode is also the default,","     so this doubles as the automatic cleanup for pages loaded directly. */","  async function blobAllPages(quiet = false) {","    els.imageLoadMode.value = \"blob\";","    scheduleSave();","","    const images = [...els.pages.querySelectorAll(\".page-wrap img\")];","    let converted = 0;","    for (const img of images) {","      if (!img.isConnected || img.dataset.blobPending === \"1\") continue;","      if (img.dataset.blob === \"1\" \u0026\u0026 img._blobObjectUrl \u0026\u0026 img.src === img._blobObjectUrl) continue;","      const url = img.dataset.remote || img.currentSrc || img.src;","      if (!url || /^(blob:|data:)/i.test(url)) continue;","      if (await setImageSource(img, url)) converted += 1;","    }","","    if (!quiet) {","      setStatus(","        converted","          ? `Blobbed ${converted} page${c