\";"]},{"start":8120,"del":0,"lines":["  els.imageLoadMode.addEventListener(\"change\", () =\u003e {","    setStatus(","      imageLoadMode() === \"blob\"","        ? \"New pages will load as Blob URLs. Reload the chapter to apply this to current pages.\"","        : \"New pages will use direct image URLs. Reload the chapter to apply this to current pages.\",","      \"status-ok\",","      3600","    );","  });",""]},{"start":8126,"del":0,"lines":["  els.blobAllBtn.addEventListener(\"click\", () =\u003e void blobAllPages());"]}];
  function patchMangaReader(text) {
    const lines = text.split(/(?<=\n)/);
    let shift = 0;
    for (const h of MANGA_READER_BLOB_ALL_PATCH) {
      lines.splice(h.start + shift, h.del, ...h.lines.map((line) => line + '\n'));
      shift += h.lines.length - h.del;
    }
    return lines.join('');
  }

  function embeddedBlob(file){
    const name = file.name;
    if (embeddedBlobCache.has(name)) return Promise.resolve(embeddedBlobCache.get(name));
    const meta = EMBEDDED_APP_SOURCES[name];
    const node = meta && document.getElementById(meta.nodeId);
    if (!node) return Promise.reject(new Error('The embedded app files are missing from this client.'));
    let text;
    try {
      const raw = atob(node.textContent.replace(/\s+/g, ''));
      const bytes = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
      text = new TextDecoder('utf-8').decode(bytes);
    } catch (err){
      return Promise.reject(new Error('The embedded app files are damaged.'));
    }
    if (name === 'Manga Reader.html' && !text.includes('function imageLoadMode()')) {
      text = patchMangaReader(text);
    }
    const blob = new Blob([new TextEncoder().encode(text)], { type: 'text/html;charset=utf-8' });
    embeddedBlobCache.set(name, blob);
    return Promise.resolve(blob);
  }

  function mountBlob(blob, token){
    const base = URL.createObjectURL(blob);
    currentUrl = base;
    let src = base;
    /* A blob: iframe opened from a file:// page has an opaque origin, so the reader
       proxy must know to skip the CORS service and use its text fallback. */
    if (currentFile && currentFile.embedded && location.protocol === 'file:') src += '#darkstar-noproxy';
    currentKind = 'blob';
    setStatus('downloaded');
    startFrame(src, token);
  }

  function startFrame(src, token){
    currentSrc = src;
    ui.pBlank.disabled = false;
    ui.progress.classList.remove('indet');
    ui.bar.style.width = '100%';
    ui.pct.textContent = '100%';
    ui.progress.setAttribute('aria-valuenow', '100');
    setStatus('starting');
    ui.loadTitle.textContent = 'Starting app…';
    ui.loadSub.textContent = 'The player is warming up';
    ui.loader.hidden = false;
    ui.error.hidden = true;

    ui.frame.onload = () => {
      if (token !== playToken) return;
      if (!ui.frame.src || ui.frame.src === 'about:blank') return;
      ui.loader.hidden = true;
      ui.error.hidden = true;
      setStatus('running');
      if (currentFile && !currentLocal){
        clearBroken(currentFile.name);
        addRecent(currentFile.name);
      }
      schedulePbarHide();
    };

    ui.frame.src = src;
  }

  function fail(err){
    ui.loader.hidden = true;
    ui.error.hidden = false;
    const message = err && err.message ? err.message : 'Unknown error.';
    ui.errMsg.textContent = message + ' You can retry, or use another source by reloading.';
    setStatus('error', 'bad');
    if (currentFile && !currentLocal) markBroken(currentFile.name);
  }

  /* ---------------- player controls ---------------- */
  function escapeHtml(value){
    return String(value).replace(/[&<>"']/g, (ch) => (
      { '&': '&', '<': '<', '>': '>', '"': '"', "'": ''' }[ch]
    ));
  }

  function jsString(value){
    return JSON.stringify(String(value))
      .replace(/</g, '\\u003c')
      .replace(/\u2028/g, '\\u2028')
      .replace(/\u2029/g, '\\u2029');
  }

  function buildPlayGate(file, src){
    const title = cleanTitle(file.name) || 'App';
    const appUrl = jsString(src);
    const cacheKey = jsString('webs.app::' + file.name);
    const appName = jsString(title);

    return `






${escapeHtml(title)}






  CLICK TO PLAY

G+
  FULLSCREEN

${escapeHtml(title)}



  var DB_NAME = 'GameCacheDB';
  var STORE_NAME = 'GameFiles';
  var CACHE_DURATION = 90 * 24 * 60 * 60 * 1000;
  var MAX_CACHE_CHARS = 16 * 1024 * 1024;
  var FILE_URL = ${appUrl};
  var CACHE_KEY = ${cacheKey};
  var APP_NAME = ${appName};

  function openDB() {
    return new Promise(function(resolve, reject) {
      if (!window.indexedDB) { reject(new Error('No IndexedDB')); return; }
      var request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = function(event) {
        var db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'url' });
        }
      };
      request.onsuccess = function(event) { resolve(event.target.result); };
      request.onerror = function(event) { reject(event.target.error); };
    });
  }

  function saveToCache(content) {
    if (content.length > MAX_CACHE_CHARS) return Promise.resolve();
    return openDB().then(function(db) {
      return new Promise(function(resolve, reject) {
        var transaction = db.transaction(STORE_NAME, 'readwrite');
        transaction.objectStore(STORE_NAME).put({ url: CACHE_KEY, content: content, timestamp: Date.now() });
        transaction.oncomplete = function() { resolve(); };
        transaction.onerror = function() { reject(transaction.error); };
        transaction.onabort = function() { reject(transaction.error); };
      });
    });
  }

  async function getFileFromCache() {
    try {
      var db = await openDB();
      var data = await new Promise(function(resolve, reject) {
        var transaction = db.transaction(STORE_NAME, 'readonly');
        var store = transaction.objectStore(STORE_NAME);
        var request = store.get(CACHE_KEY);
        request.onsuccess = function(event) { resolve(event.target.result); };
        request.onerror = function() { reject(new Error('Cache error')); };
      });
      if (data && (Date.now() - data.timestamp) < CACHE_DURATION) {
        return data.content;
      }
    } catch (err) { /* cache is optional */ }

    var response = await fetch(FILE_URL);
    if (!response.ok) throw new Error('Download failed with HTTP ' + response.status);
    var text = await response.text();
    saveToCache(text).catch(function() {});
    return text;
  }

  function PlayTo(button) {
    var iframe = document.getElementById('fr');
    var label = button.textContent;
    button.disabled = true;
    button.textContent = 'LOADING…';
    getFileFromCache().then(function(text) {
      iframe.contentDocument.open();
      iframe.contentDocument.write(text);
      iframe.contentDocument.close();
      iframe.style.display = 'block';
      button.style.display = 'none';
      try { parent.postMessage({ type: 'webs:play', name: APP_NAME }, '*'); } catch (err) {}
    }).catch(function(err) {
      console.error('Error:', err);
      button.disabled = false;
      button.textContent = label;
      alert('Could not load the app. Check your connection and try again.');
    });
  }

  function openFullscreen() {
    var newWindow = window.open('', '_blank');
    if (!newWindow) { alert('Fullscreen could not open. Allow pop-ups and try again.'); return; }
    try {
      newWindow.document.write('Loading…Loading…');
      newWindow.document.close();
    } catch (err) {}
    getFileFromCache().then(function(text) {
      newWindow.document.open();
      newWindow.document.write(text);
      newWindow.document.close();
    }).catch(function(err) {
      console.error('Error:', err);
      try { newWindow.document.body.textContent = 'Could not load the app.'; } catch (e2) {}
    });
  }
<\/script>

`;
  }

  function blankFrame(){
    if (!currentFile) return;
    if (!currentSrc){
      toast('Wait for the app to finish loading first', 'bad');
      return;
    }

    clearTimeout(pbarTimer);
    resetFrame();
    ui.loader.hidden = true;
    ui.error.hidden = true;
    ui.frame.srcdoc = buildPlayGate(currentFile, currentSrc);
    setStatus('play screen', 'warn');
  }

  function closePlayer(){
    playToken++;
    if (abortCtl){ abortCtl.abort(); abortCtl = null; }
    clearTimeout(pbarTimer);

    resetFrame();
    ui.player.hidden = true;
    document.body.classList.remove('playing');

    ui.loader.hidden = true;
    ui.error.hidden = true;
    setPbarHidden(false);

    if (currentUrl && !keptUrls.has(currentUrl)) URL.revokeObjectURL(currentUrl);
    currentUrl = null;
    currentSrc = null;
    currentFile = null;
    currentLocal = null;
    currentKind = null;

    if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
    recentDirty = false;
    render();
    if (lastFocus && lastFocus.isConnected) lastFocus.focus();
    lastFocus = null;
  }

  function reloadCurrent(){
    if (!currentFile) return;
    run(currentFile, currentLocal);
  }

  function openExternal(){
    if (!currentSrc) return;
    if (currentSrc.startsWith('blob:')) keptUrls.add(currentSrc);
    window.open(currentSrc, '_blank', 'noopener');
  }

  function openBlobManga(){
    const tab = window.open('about:blank', '_blank');
    if (!tab){
      toast('Allow popups to open Manga Reader v2 outside the launcher', 'bad');
      return;
    }

    /* The new tab fetches and blobs the reader itself, so the launcher never
       downloads or displays the manga. */
    const loader = `


Loading Manga Reader v2…
Loading Manga Reader v2…

fetch(${JSON.stringify(BLOB_MANGA_URL)}, { cache: 'no-store' })
  .then(function(res){ if (!res.ok) throw new Error('HTTP ' + res.status); return res.text(); })
  .then(function(text){
    if (!text.trim()) throw new Error('empty file');
    location.replace(URL.createObjectURL(new Blob([text], { type: 'text/html;charset=utf-8' })));
  })
  .catch(function(err){ document.body.textContent = 'Could not load Manga Reader v2 — ' + err.message; });
<\/script>

`;

    try {
      tab.document.open();
      tab.document.write(loader);
      tab.document.close();
    } catch (err){
      tab.location.href = BLOB_MANGA_URL;
    }
    toast('Opened Manga Reader v2 outside the launcher', 'good');
  }

  async function toggleFullscreen(){
    try {
      if (!document.fullscreenElement) await ui.player.requestFullscreen();
      else await document.exitFullscreen();
    } catch (err){ /* ignore */ }
  }

  function surprise(){
    const pool = files.filter((f) => inGroup(f, 'all'));
    if (!pool.length){ toast('Nothing available to play right now', 'bad'); return; }
    run(pool[Math.floor(Math.random() * pool.length)]);
  }

  ui.pClose.addEventListener('click', closePlayer);
  ui.errBack.addEventListener('click', closePlayer);
  ui.errRetry.addEventListener('click', reloadCurrent);
  ui.pReload.addEventListener('click', reloadCurrent);
  ui.pExternal.addEventListener('click', openExternal);
  ui.pFull.addEventListener('click', toggleFullscreen);
  ui.pBlank.addEventListener('click', blankFrame);
  ui.pBar.addEventListener('click', () => {
    setPbarHidden(!ui.player.classList.contains('bar-hidden'));
    if (!ui.player.classList.contains('bar-hidden')) schedulePbarHide();
  });
  ui.pBarReveal.addEventListener('click', () => {
    setPbarHidden(false);
    schedulePbarHide();
  });

  ui.player.addEventListener('mousemove', (event) => {
    if (ui.player.hidden) return;
    if (ui.player.classList.contains('bar-hidden')){
      if (event.clientY < 90){
        setPbarHidden(false);
        schedulePbarHide();
      }
    } else {
      schedulePbarHide();
    }
  });

  document.addEventListener('fullscreenchange', () => {
    ui.pFull.title = document.fullscreenElement ? 'Exit fullscreen (F)' : 'Fullscreen (F)';
    if (!document.fullscreenElement){
      clearTimeout(pbarTimer);
      setPbarHidden(false);
    } else {
      setPbarHidden(false);
      schedulePbarHide();
    }
  });

  window.addEventListener('message', (event) => {
    if (ui.player.hidden || !currentFile) return;
    if (event.source !== ui.frame.contentWindow) return;
    const data = event.data;
    if (!data || data.type !== 'webs:play') return;
    setStatus('running');
    schedulePbarHide();
  });

  /* ---------------- local files ---------------- */
  function launchLocal(file){
    if (!file) return;
    if (!/\.html?$/i.test(file.name)){
      toast('Only .html or .htm files can run here', 'bad');
      return;
    }
    run({ name: file.name, size: file.size }, file);
  }

  ui.fileInput.addEventListener('change', () => {
    const file = ui.fileInput.files && ui.fileInput.files[0];
    if (file) launchLocal(file);
    ui.fileInput.value = '';
  });

  let dragDepth = 0;
  function hasFiles(event){
    return !!(event.dataTransfer && Array.from(event.dataTransfer.types || []).includes('Files'));
  }

  window.addEventListener('dragenter', (event) => {
    if (!hasFiles(event)) return;
    event.preventDefault();
    dragDepth++;
    ui.drop.classList.add('show');
  });
  window.addEventListener('dragover', (event) => {
    if (!hasFiles(event)) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = 'copy';
  });
  window.addEventListener('dragleave', (event) => {
    if (!ui.drop.classList.contains('show')) return;
    dragDepth = Math.max(0, dragDepth - 1);
    if (dragDepth === 0 || event.relatedTarget === null){
      dragDepth = 0;
      ui.drop.classList.remove('show');
    }
  });
  window.addEventListener('drop', (event) => {
    if (!hasFiles(event)) return;
    event.preventDefault();
    dragDepth = 0;
    ui.drop.classList.remove('show');
    const file = event.dataTransfer.files && event.dataTransfer.files[0];
    if (file) launchLocal(file);
  });

  /* ---------------- URL inspector ---------------- */
  const INSPECT_PROXY_DEFS = {
    jina: {
      label: 'Jina Reader',
      make: (url) => 'https://r.jina.ai/' + url,
      headers: { 'x-respond-with': 'html' }
    },
    allorigins: {
      label: 'AllOrigins',
      make: (url) => 'https://api.allorigins.win/raw?url=' + encodeURIComponent(url),
      headers: {}
    },
    alloriginsget: {
      label: 'AllOrigins JSON',
      make: (url) => 'https://api.allorigins.win/get?url=' + encodeURIComponent(url),
      headers: {},
      json: 'contents'
    },
    codetabs: {
      label: 'CodeTabs',
      make: (url) => 'https://api.codetabs.com/v1/proxy?quest=' + encodeURIComponent(url),
      headers: {}
    }
  };
  const INSPECT_PROXY_ORDER = ['jina', 'allorigins', 'alloriginsget', 'codetabs'];
  const INS_REQUEST_TIMEOUT = 15000;
  const INS_MAX_NODES = 2600;
  const INS_MAX_SOURCE = 400000;
  const INS_MAX_CONSOLE = 400;
  const INS_MAX_NETWORK = 300;
  const INS_STYLE_GROUPS = [
    {
      name: 'Layout',
      keys: ['display', 'position', 'top', 'right', 'bottom', 'left', 'width', 'height', 'min-width', 'min-height', 'max-width', 'max-height', 'box-sizing', 'z-index', 'overflow-x', 'overflow-y', 'float', 'clear', 'flex-direction', 'flex-wrap', 'justify-content', 'align-items', 'align-content', 'gap', 'grid-template-columns', 'grid-template-rows', 'order']
    },
    {
      name: 'Spacing',
      keys: ['margin-top', 'margin-right', 'margin-bottom', 'margin-left', 'padding-top', 'padding-right', 'padding-bottom', 'padding-left', 'border-top-width', 'border-right-width', 'border-bottom-width', 'border-left-width', 'border-top-style', 'border-top-color', 'border-radius']
    },
    {
      name: 'Typography',
      keys: ['font-family', 'font-size', 'font-weight', 'font-style', 'line-height', 'letter-spacing', 'word-spacing', 'text-align', 'text-transform', 'text-decoration-line', 'text-indent', 'white-space', 'word-break', 'overflow-wrap', 'color']
    },
    {
      name: 'Background & effects',
      keys: ['background-color', 'background-image', 'background-position', 'background-size', 'background-repeat', 'border-color', 'box-shadow', 'text-shadow', 'opacity', 'transform', 'filter', 'backdrop-filter', 'transition', 'cursor', 'pointer-events']
    }
  ];

  let inspectToken = 0;
  let inspectFocus = null;
  let inspectedUrl = '';
  let inspectedSource = '';
  let inspectedVia = '';
  let inspectDoc = null;
  let insRows = new WeakMap();
  let insNodeCount = 0;
  let insSelected = null;
  let insHovered = null;
  let insPretty = store.read(LS.inspectPretty, true) !== false;
  let insEditMode = false;
  let insStyleFilter = '';
  let insProxyChoice = store.read(LS.inspectProxy, 'auto');
  let insCustomProxy = String(store.read(LS.inspectProxyUrl, '') || '');
  let insAllowScripts = !!store.read(LS.inspectScripts, false);
  let insConsole = [];
  let insNetwork = [];
  let insSelectedRequest = null;
  let insCommandHistory = [];
  let insHistoryIndex = -1;
  let insMessageBound = false;

  const insSpinner = document.createElement('div');
  insSpinner.className = 'spinner';
  insSpinner.hidden = true;
  ui.insState.querySelector('.ins-state-card').prepend(insSpinner);

  function setInsState(title, text, busy){
    ui.insState.hidden = false;
    ui.insStateTitle.textContent = title;
    ui.insStateText.textContent = text;
    const icon = ui.insState.querySelector('.ins-state-icon');
    if (icon) icon.hidden = !!busy;
    insSpinner.hidden = !busy;
  }

  function resetInspectPanes(){
    insRows = new WeakMap();
    insNodeCount = 0;
    insSelected = null;
    insHovered = null;
    insStyleFilter = '';
    ui.insHover.style.display = 'none';
    ui.insSel.style.display = 'none';
    const treeMsg = document.createElement('p');
    treeMsg.className = 'ins-empty';
    treeMsg.textContent = 'Load a page to see its DOM.';
    ui.insTree.replaceChildren(treeMsg);
    const detailMsg = document.createElement('p');
    detailMsg.className = 'ins-empty';
    detailMsg.textContent = 'Select an element in the tree or preview.';
    ui.insDetail.replaceChildren(detailMsg);
    resetSourceView();
    ui.insMeta.textContent = 'Not loaded';
  }

  function syncInsControls(){
    ui.insProxy.value = insProxyChoice;
    ui.insCustomWrap.hidden = insProxyChoice !== 'custom';
    ui.insCustomProxy.value = insCustomProxy;
    ui.insScripts.setAttribute('aria-pressed', String(insAllowScripts));
    ui.insScripts.textContent = insAllowScripts ? 'JS on' : 'JS off';
    ui.insFrame.setAttribute('sandbox', insAllowScripts ? 'allow-same-origin allow-scripts allow-forms' : 'allow-same-origin allow-forms');
    ui.insSourceNote.textContent = insAllowScripts
      ? 'Scripts run in the preview. Only use JS on sites you trust.'
      : 'Edits render in the preview. Preview strips scripts unless JS is on.';
  }

  function openInspector(value){
    if (!ui.settings.hidden) closeSettings();
    inspectFocus = document.activeElement;
    ui.inspector.hidden = false;
    document.body.classList.add('inspecting');
    setInsTab('elements');
    inspectToken++;
    inspectedUrl = '';
    inspectedSource = '';
    inspectedVia = '';
    inspectDoc = null;
    insConsole = [];
    insNetwork = [];
    insSelectedRequest = null;
    insCommandHistory = [];
    insHistoryIndex = -1;
    renderConsole();
    renderNetwork();
    ui.insFrame.removeAttribute('srcdoc');
    ui.insFrame.src = 'about:blank';
    ui.insOpen.disabled = true;
    ui.insReload.disabled = true;
    ui.insGo.disabled = false;
    ui.insEdit.disabled = true;
    syncInsControls();
    resetInspectPanes();

    const start = urlFromQuery(value) || normalizeInspectUrl(value) || (typeof store.read(LS.inspect, '') === 'string' ? store.read(LS.inspect, '') : '');
    ui.insUrl.value = start;
    if (value && normalizeInspectUrl(value)){
      loadInspectUrl(value);
      setTimeout(() => { ui.insUrl.focus(); ui.insUrl.select(); }, 40);
    } else {
      setInsState('Inspect any site', 'Paste a URL above to fetch the page and explore its DOM, attributes and styles. Scripts stay off unless you turn on JS.', false);
      setTimeout(() => { ui.insUrl.focus(); ui.insUrl.select(); }, 40);
    }
  }

  function closeInspector(){
    inspectToken++;
    ui.inspector.hidden = true;
    document.body.classList.remove('inspecting');
    inspectDoc = null;
    insSelected = null;
    insHovered = null;
    ui.insFrame.onload = null;
    ui.insFrame.removeAttribute('srcdoc');
    ui.insFrame.src = 'about:blank';
    if (inspectFocus && inspectFocus.isConnected) inspectFocus.focus();
    inspectFocus = null;
  }

  function setInsTab(name){
    document.querySelectorAll('[data-ins-tab]').forEach((btn) => {
      btn.setAttribute('aria-selected', String(btn.getAttribute('data-ins-tab') === name));
    });
    ui.insElementsPane.hidden = name !== 'elements';
    ui.insSourcePane.hidden = name !== 'source';
    ui.insConsolePane.hidden = name !== 'console';
    ui.insNetworkPane.hidden = name !== 'network';
  }

  const INS_MONITOR_SCRIPT = `(function(){
    function send(type, data){
      try { parent.postMessage({ __websIns: true, type: type, data: data }, '*'); } catch (e) {}
    }
    function fmt(v){
      try {
        if (v === undefined) return 'undefined';
        if (v === null) return 'null';
        if (typeof v === 'string') return v;
        if (typeof v === 'number' || typeof v === 'boolean' || typeof v === 'bigint') return String(v);
        if (typeof v === 'function') return 'ƒ ' + (v.name || 'anonymous') + '()';
        if (v instanceof Error) return v.name + ': ' + v.message;
        if (typeof Element !== 'undefined' && v instanceof Element) return '<' + v.tagName.toLowerCase() + (v.id ? '#' + v.id : '') + '>';
        if (typeof Node !== 'undefined' && v instanceof Node) return v.nodeName;
        if (typeof v === 'object') {
          var seen = [];
          return JSON.stringify(v, function(k, x){
            if (typeof x === 'object' && x !== null) {
              if (seen.indexOf(x) !== -1) return '[Circular]';
              seen.push(x);
            }
            return x;
          }).slice(0, 4000);
        }
        return String(v);
      } catch (e) { return String(v); }
    }
    ['log','info','warn','error','debug'].forEach(function(level){
      var orig = console[level];
      console[level] = function(){
        var args = Array.prototype.slice.call(arguments).map(fmt);
        send('console', { level: level, args: args, time: Date.now() });
        if (orig) return orig.apply(console, arguments);
      };
    });
    window.addEventListener('error', function(e){
      send('console', { level: 'error', args: [String(e.message || 'Script error') + ' @ ' + String(e.filename || '') + ':' + String(e.lineno || 0)], time: Date.now() });
    });
    window.addEventListener('unhandledrejection', function(e){
      send('console', { level: 'error', args: ['Unhandled rejection: ' + fmt(e.reason)], time: Date.now() });
    });
    var of = window.fetch;
    if (of) window.fetch = function(input, init){
      var url = (typeof Request !== 'undefined' && input instanceof Request) ? input.url : String(input);
      var method = (init && init.method) || (typeof Request !== 'undefined' && input instanceof Request ? input.method : 'GET');
      var started = performance.now();
      return of.apply(this, arguments).then(function(res){
        var headers = [];
        try { res.headers.forEach(function(v, k){ if (headers.length < 40) headers.push([k, v]); }); } catch (e) {}
        send('network', { url: res.url || url, method: String(method).toUpperCase(), status: res.status, type: 'fetch', ms: Math.round(performance.now() - started), size: Number(res.headers.get('content-length')) || 0, headers: headers, source: 'page' });
        return res;
      }, function(err){
        send('network', { url: url, method: String(method).toUpperCase(), status: 0, type: 'fetch', ms: Math.round(performance.now() - started), error: String(err), source: 'page' });
        throw err;
      });
    };
    var ox = XMLHttpRequest.prototype.open;
    var os = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function(method, url){
      this.__websReq = { method: String(method || 'GET').toUpperCase(), url: String(url || '') };
      return ox.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function(){
      var xhr = this;
      var req = xhr.__websReq || { method: 'GET', url: '' };
      var started = performance.now();
      xhr.addEventListener('loadend', function(){
        var headers = [];
        try {
          (xhr.getAllResponseHeaders() || '').trim().split(/\\r?\\n/).forEach(function(line){
            var i = line.indexOf(':');
            if (i > 0 && headers.length < 40) headers.push([line.slice(0, i).trim(), line.slice(i + 1).trim()]);
          });
        } catch (e) {}
        send('network', { url: xhr.responseURL || req.url, method: req.method, status: xhr.status, type: 'xhr', ms: Math.round(performance.now() - started), size: (xhr.responseText || '').length, headers: headers, source: 'page' });
      });
      return os.apply(this, arguments);
    };
    try {
      new PerformanceObserver(function(list){
        list.getEntries().forEach(function(e){
          if (e.initiatorType === 'fetch' || e.initiatorType === 'xmlhttprequest') return;
          send('network', { url: e.name, method: 'GET', status: e.responseStatus || 0, type: e.initiatorType || 'resource', ms: Math.round(e.duration || 0), size: e.transferSize || e.encodedBodySize || 0, source: 'resource' });
        });
      }).observe({ type: 'resource', buffered: true });
    } catch (e) {}
  })();`;

  function customProxyHref(url){
    const template = String(insCustomProxy || '').trim();
    if (!template) return '';
    if (template.includes('{url}')) return template.split('{url}').join(url);
    if (template.includes('%s')) return template.split('%s').join(encodeURIComponent(url));
    return template + (template.includes('?') ? '' : '?') + encodeURIComponent(url);
  }

  function buildInspectAttempts(url){
    const attempts = [];
    try {
      if (new URL(url).origin === location.origin) attempts.push({ name: 'direct', href: url, headers: {} });
    } catch (err){ /* ignore */ }

    const ids = [];
    if (insProxyChoice === 'custom'){
      const href = customProxyHref(url);
      if (href) attempts.push({ name: 'custom proxy', href, headers: {} });
    } else if (insProxyChoice !== 'auto'){
      ids.push(insProxyChoice);
    }
    INSPECT_PROXY_ORDER.forEach((id) => { if (!ids.includes(id)) ids.push(id); });

    ids.forEach((id) => {
      const def = INSPECT_PROXY_DEFS[id];
      if (!def) return;
      try {
        attempts.push({ name: def.label, href: def.make(url), headers: def.headers || {}, json: def.json });
      } catch (err){ /* ignore invalid proxy */ }
    });
    return attempts;
  }

  async function fetchInspectPage(url, token){
    const attempts = buildInspectAttempts(url);
    if (!attempts.length) throw new Error('Choose a proxy or add a custom proxy URL first.');

    for (const attempt of attempts){
      if (token !== inspectToken) throw new DOMException('Cancelled', 'AbortError');
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), INS_REQUEST_TIMEOUT);
      const started = performance.now();
      try {
        const res = await fetch(attempt.href, {
          cache: 'no-store',
          headers: attempt.headers,
          signal: controller.signal
        });
        const text = await res.text();
        let body = text;
        if (attempt.json){
          try {
            const parsed = JSON.parse(text);
            body = parsed && typeof parsed[attempt.json] === 'string' ? parsed[attempt.json] : '';
          } catch (err){ body = ''; }
        }
        const good = res.ok && body.length >= 24 && /<[a-z!][^>]*>/i.test(body);
        addInsNetwork({
          url: attempt.href,
          target: url,
          method: 'GET',
          status: res.status,
          type: 'proxy',
          ms: Math.round(performance.now() - started),
          size: text.length,
          via: attempt.name,
          source: 'inspector',
          ok: good
        });
        if (good) return { text: body, via: attempt.name, status: res.status };
      } catch (err){
        addInsNetwork({
          url: attempt.href,
          target: url,
          method: 'GET',
          status: 0,
          type: 'proxy',
          ms: Math.round(performance.now() - started),
          size: 0,
          via: attempt.name,
          source: 'inspector',
          error: String(err && err.message ? err.message : err)
        });
      } finally {
        clearTimeout(timer);
      }
    }
    throw new Error('Every proxy failed. The site may block readers, need a login, or be offline. Pick another proxy, add a custom one, or open it in a new tab.');
  }

  function prepareInspectHtml(html, pageUrl, allowScripts){
    const doc = new DOMParser().parseFromString(html, 'text/html');
    doc.querySelectorAll('base').forEach((node) => node.remove());
    doc.querySelectorAll('meta[http-equiv]').forEach((node) => {
      const kind = (node.getAttribute('http-equiv') || '').toLowerCase();
      if (kind === 'content-security-policy' || kind === 'refresh' || kind === 'x-frame-options') node.remove();
    });

    if (!allowScripts){
      doc.querySelectorAll('script').forEach((node) => node.remove());
      doc.querySelectorAll('*').forEach((el) => {
        for (const attr of [...el.attributes]){
          const name = attr.name.toLowerCase();
          if (name.startsWith('on')) el.removeAttribute(attr.name);
          else if ((name === 'href' || name === 'src' || name === 'action' || name === 'xlink:href') && /^\s*javascript:/i.test(attr.value)){
            el.removeAttribute(attr.name);
          }
        }
      });
    }

    const head = doc.head || doc.documentElement;
    if (allowScripts){
      const monitor = doc.createElement('script');
      monitor.textContent = INS_MONITOR_SCRIPT;
      head.prepend(monitor);
    }
    const base = doc.createElement('base');
    base.setAttribute('href', pageUrl);
    head.prepend(base);

    return '\n' + doc.documentElement.outerHTML;
  }

  async function loadInspectUrl(value){
    const url = normalizeInspectUrl(value);
    if (!url){
      setInsState('Enter a valid URL', 'Use a full http:// or https:// address, for example https://example.com.', false);
      ui.insUrl.focus();
      return;
    }

    const token = ++inspectToken;
    inspectedUrl = url;
    inspectedSource = '';
    inspectedVia = '';
    inspectDoc = null;
    insConsole = [];
    insNetwork = [];
    insSelectedRequest = null;
    if (insEditMode) exitSourceEdit(false);
    ui.insUrl.value = url;
    store.write(LS.inspect, url);
    ui.insOpen.disabled = false;
    ui.insReload.disabled = true;
    ui.insEdit.disabled = true;
    renderConsole();
    renderNetwork();
    rawResetFrame();
    resetInspectPanes();
    ui.insMeta.textContent = 'Fetching…';
    setInsState('Fetching page…', 'Downloading the HTML for ' + url, true);

    try {
      const result = await fetchInspectPage(url, token);
      if (token !== inspectToken) return;
      inspectedSource = result.text;
      inspectedVia = result.via;
      renderSourceView();

      await renderInspectorPreview(result.text, url, token);
      if (token !== inspectToken) return;

      const nodes = inspectDoc ? inspectDoc.querySelectorAll('*').length : 0;
      let host = url;
      try { host = new URL(url).host; } catch (err){ /* ignore */ }
      ui.insMeta.textContent = `${host} · ${Math.max(1, Math.round(result.text.length / 1024))} KB · ${nodes} nodes · ${result.via}`;
      ui.insMeta.title = `Fetched with ${result.via}`;
      ui.insReload.disabled = false;
      ui.insEdit.disabled = false;
      addInsConsole('info', ['Page loaded via ' + result.via + ' · ' + nodes + ' elements']);
      setInsTab('elements');
    } catch (err){
      if (token !== inspectToken) return;
      if (err && err.name === 'AbortError') return;
      resetInspectPanes();
      setInsState('Could not load this page', (err && err.message ? err.message + ' ' : '') + 'Try another proxy above, or use “Open in new tab”.', false);
      ui.insMeta.textContent = 'Load failed';
      ui.insMeta.title = '';
      ui.insReload.disabled = false;
      ui.insEdit.disabled = true;
      addInsConsole('error', [err && err.message ? err.message : String(err)]);
    }
  }

  function rawResetFrame(){
    ui.insFrame.onload = null;
    ui.insFrame.removeAttribute('srcdoc');
    ui.insFrame.src = 'about:blank';
  }

  async function renderInspectorPreview(html, pageUrl, token){
    rawResetFrame();
    const prepared = prepareInspectHtml(html, pageUrl || 'about:blank', insAllowScripts);

    await new Promise((resolve) => {
      let settled = false;
      let timer = 0;
      const finish = () => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        ui.insFrame.removeEventListener('load', finish);
        resolve();
      };
      timer = setTimeout(finish, 9000);
      ui.insFrame.addEventListener('load', finish);
      ui.insFrame.srcdoc = prepared;
    });

    if (token !== inspectToken) return false;
    inspectDoc = ui.insFrame.contentDocument;
    if (!inspectDoc || !inspectDoc.documentElement) throw new Error('The page could not be rendered.');
    ui.insState.hidden = true;
    bindInspectDoc(inspectDoc);
    buildInspectTree(inspectDoc);
    return true;
  }

  async function applyInspectorSource(text){
    const source = String(text || '');
    if (!source.trim()){
      toast('Nothing to render', 'bad');
      return;
    }

    const token = ++inspectToken;
    inspectedSource = source;
    if (insEditMode) exitSourceEdit(false);
    renderSourceView();
    ui.insState.hidden = false;
    setInsState('Rendering edits…', 'Applying your HTML to the preview.', true);

    try {
      await renderInspectorPreview(source, inspectedUrl || 'about:blank', token);
      if (token !== inspectToken) return;
      const nodes = inspectDoc ? inspectDoc.querySelectorAll('*').length : 0;
      let host = inspectedUrl || 'edited source';
      try { host = new URL(inspectedUrl).host; } catch (err){ /* ignore */ }
      ui.insMeta.textContent = `${host} · ${Math.max(1, Math.round(source.length / 1024))} KB · ${nodes} nodes · edited`;
      ui.insMeta.title = 'Rendered from the editor';
      ui.insReload.disabled = false;
      ui.insEdit.disabled = false;
      addInsConsole('info', ['Rendered edited source · ' + nodes + ' elements']);
      setInsTab('elements');
    } catch (err){
      if (token !== inspectToken) return;
      setInsState('Could not render edits', err && err.message ? err.message : String(err), false);
      ui.insMeta.textContent = 'Render failed';
      addInsConsole('error', [err && err.message ? err.message : String(err)]);
    }
  }

  function launchInspectorSource(){
    let source = insEditMode ? ui.insSourceEdit.value : inspectedSource;
    if (!source || !source.trim()){
      toast('Load or write some HTML first', 'bad');
      return;
    }
    if (inspectedUrl && !/]/i.test(source)){
      const baseTag = '';
      if (/
]*>/i.test(source)) source = source.replace(/
]*>/i, (match) => match + baseTag);
      else if (/]*>/i.test(source)) source = source.replace(/]*>/i, (match) => match + '
' + baseTag + '');
      else source = baseTag + source;
    }
    const blob = new Blob([source], { type: 'text/html' });
    const href = URL.createObjectURL(blob);
    window.open(href, '_blank', 'noopener');
    setTimeout(() => URL.revokeObjectURL(href), 60000);
    toast('Opened the edited page in a new tab', 'good');
  }

  async function copyText(value){
    const text = String(value || '');
    if (!text){
      toast('Nothing to copy', 'bad');
      return;
    }
    try {
      await navigator.clipboard.writeText(text);
      toast('Copied to clipboard', 'good');
    } catch (err){
      try {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        ta.remove();
        toast('Copied to clipboard', 'good');
      } catch (e){
        toast('Could not copy to the clipboard', 'bad');
      }
    }
  }

  /* ---------------- inspector: source view ---------------- */
  const INS_VOID_TAGS = /^(area|base|br|col|embed|hr|img|input|link|meta|param|source|track|wbr)$/i;
  const INS_RAW_TAGS = /^(script|style|pre|textarea)$/i;

  function formatHtml(source){
    const tokens = String(source || '').match(/||]*>|<\/?[a-zA-Z][^>]*>|[^<]+/g) || [];
    const out = [];
    let depth = 0;
    let rawTag = '';
    const pad = () => '  '.repeat(Math.max(0, depth));
    for (const token of tokens){
      if (rawTag){
        if (new RegExp('^</' + rawTag + '\\b', 'i').test(token)){
          depth = Math.max(0, depth - 1);
          out.push(pad() + token.trim());
          rawTag = '';
        } else {
          out.push(token.replace(/\s+$/, ''));
        }
        continue;
      }
      if (token.startsWith('</')){
        depth = Math.max(0, depth - 1);
        out.push(pad() + token.trim());
      } else if (token.startsWith('$/.test(token);
        out.push(pad() + token.trim());
        if (INS_RAW_TAGS.test(name) && !selfCloses){
          rawTag = name;
          depth++;
        } else if (!INS_VOID_TAGS.test(name) && !selfCloses){
          depth++;
        }
      } else {
        const text = token.trim();
        if (text) out.push(pad() + text);
      }
    }
    return out.join('\n');
  }

  function highlightTag(raw){
    const match = raw.match(/^<(\/?)([a-zA-Z][\w:-]*)([\s\S]*?)(\/?)>$/);
    if (!match) return '' + escapeHtml(raw) + '';
    const close = match[1] ? '/' : '';
    const name = match[2];
    const rest = match[3] || '';
    const selfClose = match[4] ? '/' : '';
    let out = '<' + close + '' + escapeHtml(name) + '';
    const attrRe = /([^\s=]+)(\s*=\s*)("[^"]*"|'[^']*'|[^\s>]+)?/g;
    let last = 0;
    let attr;
    while ((attr = attrRe.exec(rest))){
      if (attr.index > last) out += escapeHtml(rest.slice(last, attr.index));
      out += '' + escapeHtml(attr[1]) + '';
      if (attr[2]) out += '' + escapeHtml(attr[2]) + '';
      if (attr[3]) out += '' + escapeHtml(attr[3]) + '';
      last = attr.index + attr[0].length;
    }
    if (last < rest.length) out += escapeHtml(rest.slice(last));
    out += '' + (selfClose ? '/' : '') + '>';
    return out;
  }

  function highlightHtml(source){
    return String(source || '').split('\n').map((line) => {
      const re = /|<\/?[a-zA-Z][^>]*>/g;
      let out = '';
      let last = 0;
      let match;
      while ((match = re.exec(line))){
        if (match.index > last) out += escapeHtml(line.slice(last, match.index));
        out += match[0].startsWith('


